import 'package:flutter/material.dart';import 'package:pos_app/core/app_services.dart';import 'package:pos_app/core/utils/money.dart';import 'package:pos_app/features/pos/data/pos_repository.dart';import 'package:pos_app/features/pos/domain/cart.dart';
class PosScreen extends StatefulWidget{const PosScreen({super.key});@override State<PosScreen> createState()=>_PosScreenState();}class _PosScreenState extends State<PosScreen>{final lines=<CartLine>[];bool busy=false;Future<void> addProduct() async {final db=await appDatabase.open();final rows=await db.rawQuery('SELECT p.id,p.global_id,p.name,p.sale_price_cents,COALESCE(SUM(l.available_quantity),0) stock FROM products p LEFT JOIN inventory_lots l ON l.product_id=p.id AND l.active=1 WHERE p.active=1 GROUP BY p.id ORDER BY p.name LIMIT 100');if(!mounted)return;final row=await showDialog<Map<String,Object?>>(context:context,builder:(d)=>SimpleDialog(title:const Text('Selecciona producto'),children:rows.map((r)=>SimpleDialogOption(onPressed:()=>Navigator.pop(d,r),child:Text('${r['name']} · stock ${r['stock']} · ${formatMoney(r['sale_price_cents'] as int)}'))).toList()));if(row!=null)setState(()=>lines.add(CartLine(productId:row['id'] as int,productGlobalId:row['global_id'] as String,name:row['name'] as String,quantity:1,unitPriceCents:row['sale_price_cents'] as int)));}
 @override Widget build(BuildContext context){final total=calculateSaleTotals(lines).totalCents;return Scaffold(appBar:AppBar(title:const Text('Nueva venta')),floatingActionButton:FloatingActionButton(onPressed:addProduct,child:const Icon(Icons.add)),body:Row(children:[Expanded(child:ListView.builder(itemCount:lines.length,itemBuilder:(c,i){final l=lines[i];return ListTile(title:Text(l.name),subtitle:Text(formatMoney(l.unitPriceCents)),trailing:Wrap(crossAxisAlignment:WrapCrossAlignment.center,children:[IconButton(onPressed:()=>setState(()=>l.quantity=l.quantity>1?l.quantity-1:1),icon:const Icon(Icons.remove)),Text('${l.quantity}'),IconButton(onPressed:()=>setState(()=>l.quantity++),icon:const Icon(Icons.add)),Text(formatMoney(l.totalCents))]));})),SizedBox(width:320,child:Card(child:Padding(padding:const EdgeInsets.all(20),child:Column(mainAxisAlignment:MainAxisAlignment.end,children:[Text('TOTAL',style:Theme.of(context).textTheme.titleLarge),Text(formatMoney(total),style:Theme.of(context).textTheme.displaySmall),const SizedBox(height:18),FilledButton(onPressed:busy||lines.isEmpty?null:()async{setState(()=>busy=true);try{await PosRepository(appDatabase).completeSale(lines,paymentMethod:'Cash',receivedCents:total);if(mounted)setState(lines.clear);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}finally{if(mounted)setState(()=>busy=false);}},child:const Text('COBRAR EFECTIVO'))]))))]);}}
